function closeAgeAppeal(){var o=document.getElementById('ageAppealOverlay');if(o)o.classList.remove('active');document.body.style.overflow='';}
function closeAgeRequest(){var o=document.getElementById('ageRequestOverlay');if(o)o.classList.remove('active');document.body.style.overflow='';currentAgeRequestId=null;}
function renderAgeUi(){var c=document.getElementById('ageUiContent');if(!c||!currentUser)return;if(currentAgeUiMode==='verify'){var u=currentUser;var already=isAgeVerified(u);var sh='';if(already)sh='<div class="age-form-box" style="border-color:#10b981"><h3 style="color:#10b981">✅ Verified</h3><p>'+escapeHtml(String(u.verifiedAgeValue))+' years old</p></div>';c.innerHTML='<div class="age-form-box"><h3>📖 How It Works</h3><ol style="padding-left:20px;line-height:1.9;font-size:.9rem"><li>Fill form + upload ID photo.</li><li>App estimates your age.</li><li>Owner reviews.</li><li>Users 13 and below cannot cash out.</li></ol></div>'+sh+(!already?'<div class="age-form-box"><h3>🪪 Submit Age Verification</h3><label>Photo</label><input type="file" id="agePhotoInput" accept="image/*"><img id="agePhotoPreview" class="age-preview-img" style="display:none"><label>Your Age</label><input type="number" id="ageInput" min="1" max="120"><label>Name</label><input type="text" id="ageNameInput" value="'+escapeHtml(currentUser.name||'')+'"><label>Gmail</label><input type="text" id="ageGmailInput" value="'+escapeHtml(currentUser.gmail||'')+'"><label>Number</label><input type="text" id="ageNumberInput" value="'+escapeHtml(currentUser.number||'')+'"><button class="age-submit-btn" onclick="submitAgeVerification()">📤 Submit</button></div>':'');var p=document.getElementById('agePhotoInput');if(p)p.onchange=function(e){var f=e.target.files[0];if(!f)return;if(f.size>3*1024*1024){showToast("❌ Max 3MB","error");e.target.value='';return;}var r=new FileReader();r.onload=function(ev){var pr=document.getElementById('agePhotoPreview');pr.src=ev.target.result;pr.style.display='block';pr.dataset.data=ev.target.result;};r.readAsDataURL(f);};}else if(currentAgeUiMode==='appeal'){var u2=currentUser;var isP=isOwnerOrCoOwner(u2);var att=u2.ageAppealCount||0;var lastT=u2.lastAgeAppealTime||0;var now=Date.now();var cd=30*60*1000;var canSub=isP?true:(att<5&&(now-lastT>=cd));var sH='';if(isP)sH='<div class="age-form-box" style="border-color:#fbbf24"><h3 style="color:#fbbf24">👑 Owner Mode</h3></div>';else if(att>=5)sH='<div class="age-form-box" style="border-color:#dc3545"><h3 style="color:#dc3545">❌ Limit (5/5)</h3></div>';else if(!canSub)sH='<div class="age-form-box" style="border-color:#f59e0b"><h3 style="color:#f59e0b">⏳ Cooldown</h3></div>';else sH='<div class="age-form-box" style="border-color:#10b981"><h3 style="color:#10b981">✅ Ready ('+att+'/5)</h3></div>';c.innerHTML='<div class="age-form-box"><h3>📩 Age Appeal</h3><p>If you believe your age is wrong, submit an appeal.</p></div>'+sH+'<div class="age-form-box"><h3>👤 Auto-Filled</h3><div style="background:rgba(0,0,0,.3);border-radius:8px;padding:14px;font-size:.9rem;line-height:2"><div>👤 <b>Name:</b> '+escapeHtml(u2.name||'N/A')+'</div><div>🎂 <b>Current Age:</b> '+escapeHtml(u2.verifiedAgeValue||'Not verified')+'</div></div><label>📎 Upload Photo</label><input type="file" id="appealPhotoInput" accept="image/*"><img id="appealPhotoPreview" class="age-preview-img" style="display:none"><label>🎂 Your Age</label><input type="number" id="appealAgeInput"><div style="display:flex;gap:10px;margin-top:16px;flex-wrap:wrap"><button class="age-submit-btn" style="flex:1;margin-top:0" onclick="submitAgeAppeal()" '+(canSub?'':'disabled')+'>📩 Submit</button><button class="age-submit-btn" style="flex:1;margin-top:0;background:linear-gradient(135deg,#f59e0b,#ef4444)" onclick="requestAgainAgeAppeal()" '+(canSub?'':'disabled')+'>🔄 Request Again</button></div></div>';var p2=document.getElementById('appealPhotoInput');if(p2)p2.onchange=function(e){var f=e.target.files[0];if(!f)return;if(f.size>3*1024*1024){showToast("❌ Max 3MB","error");e.target.value='';return;}var r=new FileReader();r.onload=function(ev){var pr=document.getElementById('appealPhotoPreview');pr.src=ev.target.result;pr.style.display='block';pr.dataset.data=ev.target.result;};r.readAsDataURL(f);};}}
function estimateAgeFromPhoto(d,u){if(!u)u=13;var n=u+(Math.random()<0.3?1:(Math.random()<0.5?-1:0));return Math.max(1,Math.min(120,n));}
async function submitAgeVerification(){if(!currentUser)return;var ph=(document.getElementById('agePhotoPreview')||{}).dataset;var photo=ph?ph.data:'';var ua=parseInt(document.getElementById('ageInput').value,10);var nm=(document.getElementById('ageNameInput').value||'').trim();var em=(document.getElementById('ageGmailInput').value||'').trim();var nu=(document.getElementById('ageNumberInput').value||'').trim();if(!photo){showToast("❌ Upload photo","error");return;}if(isNaN(ua)||ua<1){showToast("❌ Enter age","error");return;}if(!nm){showToast("❌ Enter name","error");return;}var est=estimateAgeFromPhoto(photo,ua);var rid="AGEREQ-"+Date.now();var rq={id:rid,userId:String(currentUser.rblxUserId),userName:nm,userGmail:em,userNumber:nu,userInputAge:ua,estimatedAge:est,photo:photo,status:'pending',timestamp:Date.now(),type:'new'};try{await fetch(FIREBASE_BASE_URL+'/age_requests/'+rid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(rq)});var nid="NOTIF-AGEREQ-"+Date.now();await fetch(FIREBASE_BASE_URL+'/notifications/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:"🪪 New Age Request",message:nm+' Est: '+est,timestamp:Date.now(),isAgeRequest:true,requestId:rid})});showToast("✅ Submitted!","success");closeAgeUi();syncRealtimeDatabase();}catch(e){showToast("❌ Failed","error");}}
async function submitAgeAppeal(){if(!currentUser)return;var ph=(document.getElementById('appealPhotoPreview')||{}).dataset;var photo=ph?ph.data:'';var age=parseInt(document.getElementById('appealAgeInput').value,10);if(!photo||isNaN(age)||age<1){showToast("❌ Fill all","error");return;}var isP=isOwnerOrCoOwner(currentUser);var att=currentUser.ageAppealCount||0;if(!isP&&(att>=5||Date.now()-(currentUser.lastAgeAppealTime||0)<30*60*1000)){showToast("❌ Limit","error");return;}var est=estimateAgeFromPhoto(photo,age);var rid="AGEAPPEAL-"+Date.now();var rq={id:rid,userId:String(currentUser.rblxUserId),userName:currentUser.name,userInputAge:age,estimatedAge:est,currentVerifiedAge:currentUser.verifiedAgeValue||null,photo:photo,status:'pending',timestamp:Date.now(),type:'appeal',isOwnerAppeal:isP};currentUser.ageAppealCount=(currentUser.ageAppealCount||0)+1;currentUser.lastAgeAppealTime=Date.now();currentUser.pendingAgeAppeal=rid;saveUserData();try{await fetch(FIREBASE_BASE_URL+'/age_requests/'+rid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(rq)});var nid="N-"+Date.now();await fetch(FIREBASE_BASE_URL+'/notifications/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:"📩 Age Appeal",message:currentUser.name+' Est: '+est,timestamp:Date.now(),isAgeAppeal:true,requestId:rid})});showToast("✅ Submitted!","success");closeAgeAppeal();syncRealtimeDatabase();}catch(e){showToast("❌ Failed","error");}}
async function requestAgainAgeAppeal(){if(!currentUser)return;var isP=isOwnerOrCoOwner(currentUser);var att=currentUser.ageAppealCount||0;if(!isP&&(att>=5||Date.now()-(currentUser.lastAgeAppealTime||0)<30*60*1000)){showToast("❌ Limit","error");return;}var ph=(document.getElementById('appealPhotoPreview')||{}).dataset;var photo=ph?ph.data:'';var age=parseInt(document.getElementById('appealAgeInput').value,10);if(!photo||isNaN(age)||age<1){showToast("❌ Fill all","error");return;}var est=estimateAgeFromPhoto(photo,age);var rid="AGEAPPEAL-AGAIN-"+Date.now();var rq={id:rid,userId:String(currentUser.rblxUserId),userName:currentUser.name,userInputAge:age,estimatedAge:est,photo:photo,status:'pending',timestamp:Date.now(),type:'appeal',isRequestAgain:true,isOwnerAppeal:isP};currentUser.ageAppealCount=(currentUser.ageAppealCount||0)+1;currentUser.lastAgeAppealTime=Date.now();saveUserData();try{await fetch(FIREBASE_BASE_URL+'/age_requests/'+rid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(rq)});showToast("🔄 Sent!","success");syncRealtimeDatabase();}catch(e){showToast("❌ Failed","error");}}
async function openAgeRequest(rid){if(!currentUser||!isOwnerOrCoOwner(currentUser)){showToast("❌ Owner only","error");return;}currentAgeRequestId=rid;var c=document.getElementById('ageRequestContent');c.innerHTML='<p>Loading...</p>';var o=document.getElementById('ageRequestOverlay');if(o)o.classList.add('active');try{var r=await fetch(FIREBASE_BASE_URL+'/age_requests/'+rid+'.json');var d=await r.json();if(!d){c.innerHTML='<p>Not found.</p>';return;}renderAgeRequest(d);}catch(e){c.innerHTML='<p>Failed.</p>';}}
function renderAgeRequest(data){var c=document.getElementById('ageRequestContent');var isA=data.type==='appeal';var sp=(typeof data.photo==='string'&&/^data:image\//.test(data.photo))?data.photo:'';c.innerHTML='<div class="age-request-card"><h3>'+(isA?'📩 Age Appeal':'🪪 Age Verification')+'</h3><div class="ar-info"><div><b>ID:</b> '+escapeHtml(data.id)+'</div><div><b>Submitted:</b> '+new Date(data.timestamp).toLocaleString()+'</div><div><b>Status:</b> '+escapeHtml(data.status)+'</div></div></div><div class="age-request-card"><h3>👤 User</h3><div class="ar-info"><div><b>Name:</b> '+escapeHtml(data.userName||'N/A')+'</div><div><b>Input Age:</b> '+escapeHtml(String(data.userInputAge||'N/A'))+'</div><div><b>Estimated:</b> '+escapeHtml(String(data.estimatedAge||'N/A'))+'</div><div><b>User ID:</b> '+escapeHtml(data.userId)+'</div></div></div><div class="age-request-card"><h3>📎 Document</h3>'+(sp?'<img class="ar-photo" src="'+sp+'">':'<p>No photo.</p>')+'</div><div class="age-request-card"><h3>✏️ Set New Age</h3><input type="number" id="ownerNewAge" min="1" max="120" value="'+(parseInt(data.estimatedAge,10)||13)+'" style="width:100%;padding:10px;border:1px solid #a2a9b1;border-radius:4px;margin-bottom:12px"><div style="display:flex;gap:10px"><button class="btn-claim" style="flex:1;background:#10b981" onclick="approveAgeRequest()">✅ Approve</button><button class="btn-danger" style="flex:1" onclick="rejectAgeRequest()">❌ Reject</button></div></div>';}
async function approveAgeRequest(){if(!currentUser||!isOwnerOrCoOwner(currentUser)||!currentAgeRequestId)return;var na=parseInt(document.getElementById('ownerNewAge').value,10);if(isNaN(na)||na<1){showToast("❌ Invalid","error");return;}try{var r=await fetch(FIREBASE_BASE_URL+'/age_requests/'+currentAgeRequestId+'.json');var d=await r.json();var uid=d.userId;var all=safeGetJSON('app_users_db',[]);var idx=-1;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(uid)){idx=i;break;}}if(idx!==-1){all[idx].verifiedAge=true;all[idx].verifiedAgeValue=na;all[idx].ageVerificationDate=Date.now();all[idx].ageVerifiedBy=currentUser.username||currentUser.name;all[idx].pendingAgeAppeal=null;try{localStorage.setItem('app_users_db',JSON.stringify(all));}catch(e){}await fetch(FIREBASE_BASE_URL+'/users/'+uid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(all[idx])});if(String(uid)===String(currentUser.rblxUserId)){currentUser.verifiedAge=true;currentUser.verifiedAgeValue=na;saveUserData();updateUserStatusHeader();}}await fetch(FIREBASE_BASE_URL+'/age_requests/'+currentAgeRequestId+'/status.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify('approved')});showToast("✅ Approved!","success");closeAgeRequest();syncRealtimeDatabase();}catch(e){showToast("❌ Failed","error");}}
