function generateImgShotCode(){var ch='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';var c='xdrgimg';for(var i=0;i<6;i++)c+=ch[Math.floor(Math.random()*ch.length)];return c;}
function openVideoShares(){vsTab='fyt';document.querySelectorAll('.tt-tab').forEach(function(b){b.classList.toggle('active',b.dataset.tab==='fyt');});openSwapUI('videoSharesOverlay');renderImgShotFeed();}
