function getFilteredImgShots(){var all=getAllImgShots();if(!currentUser)return all;if(vsTab==='friends'){var fids=(currentUser.friends||[]).map(String);return all.filter(function(v){return fids.indexOf(String(v.uploaderId))!==-1;});}if(vsTab==='following'){var fls=(currentUser.following||[]).map(String);return all.filter(function(v){return fls.indexOf(String(v.uploaderId))!==-1;});}return all.slice().sort(function(a,b){return (b.timestamp||0)-(a.timestamp||0);});}
function isFollowingUser(uid){if(!currentUser)return false;return (currentUser.following||[]).map(String).indexOf(String(uid))!==-1;}
function renderImgShotFeed(){var feed=document.getElementById('ttFeed');if(!feed)return;if(ttObserver){ttObserver.disconnect();ttObserver=null;}var meId=currentUser?String(currentUser.rblxUserId):'guest';var list=getFilteredImgShots().reverse();if(list.length===0){feed.innerHTML='<div class="tt-item"><div class="tt-empty">📭 No images yet.</div></div>';return;}var allUsers=safeGetJSON('app_users_db',[]);feed.innerHTML=list.map(function(v){var liked=(v.likes||[]).map(String).indexOf(meId)!==-1;var saved=(v.savedBy||[]).map(String).indexOf(meId)!==-1;var following=isFollowingUser(v.uploaderId);var isMe=String(v.uploaderId)===meId;var av=getRobloxAvatarUrl(v.uploaderId);var up=null;for(var i=0;i<allUsers.length;i++){if(String(allUsers[i].rblxUserId)===String(v.uploaderId)){up=allUsers[i];break;}}var vb=verifiedBadgeHtml(up);var ab=up?getAgeBadge(up):'';var mh=v.media?'<img class="tt-media" src="'+escapeHtml(v.media)+'">':'<div class="tt-media" style="display:flex;align-items:center;justify-content:center;font-size:6rem">🖼️</div>';return '<div class="tt-item">'+mh+'<div class="tt-overlay-left"><div class="tt-uploader-row"><img class="tt-avatar" src="'+av+'" onerror="this.onerror=null;this.src=\''+DEFAULT_AVATAR+'\'"><div><div class="tt-uploader-name">@'+escapeHtml(v.uploaderUsername||'user')+vb+ab+'</div></div></div><div class="tt-title">'+escapeHtml(v.title||'Untitled')+'</div>'+(v.description?'<div class="tt-desc">'+escapeHtml(v.description)+'</div>':'')+'<div class="tt-code-tag">'+escapeHtml(v.code||'')+'</div></div><div class="tt-overlay-right"><button class="tt-action"><img class="tt-action-avatar" src="'+av+'" onerror="this.onerror=null;this.src=\''+DEFAULT_AVATAR+'\'"></button>'+(isMe?'':'<button class="tt-action" onclick="followUserToggle(\''+v.uploaderId+'\')"><span class="tt-action-icon">'+(following?'✓':'➕')+'</span><span>'+(following?'Following':'Follow')+'</span></button>')+'<button class="tt-action" onclick="toggleImgShotLike(\''+v.id+'\')"><span class="tt-action-icon">'+(liked?'❤️':'🤍')+'</span><span>'+(v.likes||[]).length+'</span></button><button class="tt-action" onclick="toggleImgShotSave(\''+v.id+'\')"><span class="tt-action-icon">'+(saved?'⭐':'🔖')+'</span><span>'+(saved?'Saved':'Save')+'</span></button><button class="tt-action" onclick="shareImgShot(\''+v.id+'\')"><span class="tt-action-icon">↗️</span><span>'+(v.views||0)+'👁</span></button></div></div>';}).join('');}
