function renderClaimedRewards(){var c=document.getElementById('claimedRewardsContent');if(!c)return;if(!currentUser){c.innerHTML='<p style="text-align:center">Login required.</p>';return;}var meId=String(currentUser.rblxUserId);var my=getAllImgShots().filter(function(v){return String(v.uploaderId)===meId;});var tv=my.reduce(function(s,v){return s+(v.views||0);},0);var tl=my.reduce(function(s,v){return s+(v.likes||[]).length;},0);var tf=(currentUser.followers||[]).length;var te=(tf*10)+(tl*5)+Math.floor(tv/10);c.innerHTML='<div style="max-width:900px;margin:0 auto;padding:20px"><div style="background:linear-gradient(135deg,#059669,#10b981);padding:24px;border-radius:14px;text-align:center"><h2 style="margin:0;border:none;color:#fff">💸 Monetization</h2><div style="font-size:2.4rem;font-weight:900;color:#fff;margin:8px 0">🪙 '+te.toLocaleString()+'</div></div></div>';}
function openUploadUI(){if(!currentUser){showToast("❌ Login first","error");return;}uploadFileData=null;var fi=document.getElementById('ttFileInput');if(fi)fi.value='';var ti=document.getElementById('ttUploadTitle');if(ti)ti.value='';var de=document.getElementById('ttUploadDesc');if(de)de.value='';var pv=document.getElementById('ttUploadPreview');if(pv){pv.style.display='none';pv.innerHTML='';}var m=document.getElementById('uploadModal');if(m)m.classList.add('active');}
