function handleUploadFile(input){var f=input.files&&input.files[0];if(!f)return;if(f.size>6*1024*1024){showToast("❌ Max 6MB","error");input.value='';return;}if((f.type||'').indexOf('image/')!==0){showToast("❌ Images only","error");input.value='';return;}var r=new FileReader();r.onload=function(e){uploadFileData={dataUrl:e.target.result};var pv=document.getElementById('ttUploadPreview');if(pv){pv.style.display='flex';pv.innerHTML='<img src="'+e.target.result+'">';}};r.readAsDataURL(f);}
async function submitUpload(){if(!currentUser)return;var t=(document.getElementById('ttUploadTitle').value||'').trim();var d=(document.getElementById('ttUploadDesc').value||'').trim();if(!t){showToast("❌ Title required","error");return;}if(!uploadFileData){showToast("❌ Pick image","error");return;}var code=generateImgShotCode();var vid="IMG-"+Date.now();var obj={id:vid,code:code,title:t,description:d,media:uploadFileData.dataUrl,mediaType:'image',uploaderId:String(currentUser.rblxUserId),uploaderName:currentUser.displayName||currentUser.name,uploaderUsername:currentUser.username,views:0,likes:[],savedBy:[],timestamp:Date.now()};var all=getAllImgShots();all.push(obj);saveAllImgShots(all);try{await fetch(FIREBASE_BASE_URL+'/img_shots/'+vid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(obj)});}catch(e){}closeUploadUI();showToast("✅ Uploaded! "+code,"success");renderImgShotFeed();}
function toggleImgShotLike(id){if(!currentUser){showToast("❌ Login","error");return;}var me=String(currentUser.rblxUserId);var all=getAllImgShots();var v=null;for(var i=0;i<all.length;i++){if(all[i].id===id){v=all[i];break;}}if(!v)return;if(!v.likes)v.likes=[];var ix=v.likes.map(String).indexOf(me);if(ix===-1)v.likes.push(me);else v.likes.splice(ix,1);saveAllImgShots(all);fetch(FIREBASE_BASE_URL+'/img_shots/'+id+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(v)}).catch(function(){});renderImgShotFeed();}
