function shareImgShot(id){var all=getAllImgShots();var v=null;for(var i=0;i<all.length;i++){if(all[i].id===id){v=all[i];break;}}if(!v)return;var url=window.location.protocol+'//'+window.location.host+window.location.pathname+'?xdrgimg='+v.code;if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(url).then(function(){showToast("🔗 Copied!","success");},function(){prompt("Copy:",url);});}else prompt("Copy:",url);}
async function followUserToggle(tid){if(!currentUser){showToast("❌ Login","error");return;}var me=String(currentUser.rblxUserId);var t=String(tid);if(me===t)return;if(!currentUser.following)currentUser.following=[];var ix=currentUser.following.map(String).indexOf(t);var nowF=ix===-1;if(nowF)currentUser.following.push(t);else currentUser.following.splice(ix,1);saveUserData();var all=safeGetJSON('app_users_db',[]);var ti=-1;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===t){ti=i;break;}}if(ti!==-1){if(!all[ti].followers)all[ti].followers=[];var fi=all[ti].followers.map(String).indexOf(me);if(nowF&&fi===-1)all[ti].followers.push(me);else if(!nowF&&fi!==-1)all[ti].followers.splice(fi,1);try{localStorage.setItem('app_users_db',JSON.stringify(all));}catch(e){}fetch(FIREBASE_BASE_URL+'/users/'+t+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(all[ti])}).catch(function(){});}renderImgShotFeed();}
