function getSpinCooldownRemaining(){var last=safeGetJSON('spin_last_'+((currentUser&&currentUser.rblxUserId)||'guest'),0);return Math.max(0,30*60*1000-(Date.now()-last));}
function formatSpinTime(ms){var s=Math.floor(ms/1000);var m=Math.floor(s/60);var sec=s%60;return String(m).padStart(2,'0')+':'+String(sec).padStart(2,'0');}
function renderLuckySpinOverlay(){var c=document.getElementById('luckySpinContent');var rem=getSpinCooldownRemaining();var hasExtra=currentUser&&(currentUser.extraSpins||0)>0;var ready=rem<=0||hasExtra;var n=SPIN_SEGMENTS.length;var sa=360/n;var conic=[];SPIN_SEGMENTS.forEach(function(s,i){conic.push(s.color+' '+(i*sa)+'deg '+((i+1)*sa)+'deg');});var lh='';SPIN_SEGMENTS.forEach(function(s,i){var a=i*sa+sa/2;lh+='<div class="spin-label" style="transform:translate(-50%,-50%) rotate('+a+'deg) translateY(-115px);"><span style="display:inline-block;transform:rotate('+(-a)+'deg);">'+s.label+'</span></div>';});var lg=SPIN_SEGMENTS.map(function(s){return '<div><span>'+s.label+'</span><small style="opacity:.7">'+s.weight+'%</small></div>';}).join('');var bl;if(ready&&hasExtra&&rem>0)bl='🎯 SPIN NOW ('+currentUser.extraSpins+' Extra)';else if(ready)bl='🎯 SPIN NOW';else bl='⏳ '+formatSpinTime(rem);c.innerHTML='<div style="text-align:center;padding:20px 0"><h2 style="color:#fbbf24;border:none;margin-bottom:8px">🎰 Lucky Spin</h2><p style="color:#94a3b8">Every 30 minutes!</p><div class="spin-wheel-box"><div class="spin-pointer">🔻</div><div class="spin-wheel" id="spinWheel" style="transform:rotate('+spinRotation+'deg);background:conic-gradient('+conic.join(',')+')">'+lh+'<div class="spin-center">SPIN</div></div></div><button class="spin-btn" id="spinBtn" '+(ready?'':'disabled')+' onclick="doLuckySpin()">'+bl+'</button><div class="spin-legend">'+lg+'</div></div>';if(!ready){if(window._spinCdInt)clearInterval(window._spinCdInt);window._spinCdInt=setInterval(function(){var b=document.getElementById('spinBtn');if(!b){clearInterval(window._spinCdInt);window._spinCdInt=null;return;}var r=getSpinCooldownRemaining();if(r<=0){b.disabled=false;b.textContent='🎯 SPIN NOW';clearInterval(window._spinCdInt);window._spinCdInt=null;}else b.textContent='⏳ '+formatSpinTime(r);},1000);}}
function doLuckySpin(){if(spinInProgress)return;var rem=getSpinCooldownRemaining();var hasExtra=currentUser&&(currentUser.extraSpins||0)>0;var useExtra=rem>0&&hasExtra;if(rem>0&&!hasExtra){showToast("⏳ Wait "+formatSpinTime(rem),"info");return;}spinInProgress=true;var b=document.getElementById('spinBtn');if(b)b.disabled=true;var tw=SPIN_SEGMENTS.reduce(function(a,s){return a+s.weight;},0);var r=Math.random()*tw;var wi=0,acc=0;for(var i=0;i<SPIN_SEGMENTS.length;i++){acc+=SPIN_SEGMENTS[i].weight;if(r<=acc){wi=i;break;}}var seg=SPIN_SEGMENTS[wi];var n=SPIN_SEGMENTS.length;var sa=360/n;var center=wi*sa+sa/2;var cm=((spinRotation%360)+360)%360;var tm=(360-center+360)%360;var delta=(tm-cm+360)%360;spinRotation+=360*5+delta;var w=document.getElementById('spinWheel');if(w)w.style.transform='rotate('+spinRotation+'deg)';setTimeout(async function(){spinInProgress=false;if(useExtra){currentUser.extraSpins=(currentUser.extraSpins||0)-1;saveUserData();}else try{localStorage.setItem('spin_last_'+((currentUser&&currentUser.rblxUserId)||'guest'),JSON.stringify(Date.now()));}catch(e){}var msg='';if(seg.vip){if(currentUser){currentUser.isVIP=true;saveUserData();updateUserStatusHeader();}msg='⭐ VIP 24h!';}else if(seg.cash){if(currentUser){currentUser.cashBalance=(currentUser.cashBalance||0)+seg.cash;saveUserData();}msg='💰 PHP ₱'+seg.cash+'!';}else if(seg.nothing){msg='😭 Nothing!';}else if(seg.extraSpins){if(currentUser){currentUser.extraSpins=(currentUser.extraSpins||0)+seg.extraSpins;saveUserData();}msg='🎉 '+seg.extraSpins+' Extra Spins!';}else if(seg.verifiedTrial){if(currentUser){currentUser.isVerified=true;currentUser.verifiedExpiry=Date.now()+30*24*3600*1000;saveUserData();updateUserStatusHeader();}msg='🔵 Verified Badge (1mo)!';}else if(seg.coins){if(currentUser){currentUser.points=(currentUser.points||0)+seg.coins;saveUserData();updateUserStatusHeader();}msg='🪙 '+seg.coins.toLocaleString()+' Coins!';}if(currentUser){var nid="SPIN-"+Date.now();globalNotifications.unshift({id:nid,title:"🎰 Lucky Spin Result",message:'You won '+msg,timestamp:Date.now()});renderNotificationDropdown();}showToast('🎉 You won: '+msg,'success');if(!seg.nothing){triggerConfetti();sfxCoin();}renderLuckySpinOverlay();},4600);}
